const $=id=>document.getElementById(id),source=$('sourceCanvas'),overlay=$('overlay'),ctx=source.getContext('2d'),paintCanvas=document.createElement('canvas');paintCanvas.width=paintCanvas.height=512;const pctx=paintCanvas.getContext('2d'),octx=overlay.getContext('2d');
let original=null,loaded=false,busy=false,drawing=false,tool='paint',last=null,undo=[],token=null,references=[],currentJob=null,lastError=null;
const notice=(message,error=false)=>{$('notice').textContent=message;$('notice').classList.toggle('error',error)};
const imageFrom=url=>new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(new Error('This image could not be opened. Try PNG or JPEG.'));im.src=url});
function maskPresent(){const a=pctx.getImageData(0,0,512,512).data;for(let i=3;i<a.length;i+=4)if(a[i]>127)return true;return false}
function controls(){ $('run').disabled=busy||!loaded||!maskPresent()||($('backbone').value==='reference'&&references.length<3);$('undo').disabled=busy||!undo.length;for(const id of ['imageFile','maskFile','framing','paint','erase','clear','backbone','mode','sample','referenceFiles','blend','detail'])$(id).disabled=busy; }
function renderMask(){octx.clearRect(0,0,512,512);if($('showMask').checked){octx.drawImage(paintCanvas,0,0);octx.globalCompositeOperation='source-in';octx.fillStyle='rgba(255,108,56,.48)';octx.fillRect(0,0,512,512);octx.globalCompositeOperation='source-over'}controls()}
function resetResult(){for(const id of ['download','downloadMask']){$(id).removeAttribute('href');$(id).classList.add('disabled');$(id).setAttribute('aria-disabled','true')}$('comparison').hidden=true;$('emptyResult').hidden=false;$('compare').disabled=true;$('resultBadge').textContent='Ready when you are'}
function snapshot(){undo.push(pctx.getImageData(0,0,512,512));if(undo.length>30)undo.shift()}
function frame(){if(!original)return;ctx.fillStyle='#11171b';ctx.fillRect(0,0,512,512);const w=original.naturalWidth,h=original.naturalHeight;if($('framing').value==='crop'){const side=Math.min(w,h);ctx.drawImage(original,(w-side)/2,(h-side)/2,side,side,0,0,512,512)}else{const s=512/Math.max(w,h);ctx.drawImage(original,(512-w*s)/2,(512-h*s)/2,w*s,h*s)}pctx.clearRect(0,0,512,512);undo=[];loaded=true;$('emptyInput').hidden=true;resetResult();renderMask()}
async function loadImage(file){if(busy)return;if(file.size>20*1024*1024)throw new Error('Please choose an image smaller than 20 MB.');const url=URL.createObjectURL(file);try{original=await imageFrom(url);references=[];renderReferences();frame();$('sourceName').textContent=file.name;notice($('backbone').value==='reference'?'New image loaded. Add matching reference photos for this person, then mark the damaged area.':'Paint over the area to reconstruct. You can adjust the framing first.')}finally{URL.revokeObjectURL(url)}}
function applyMask(im){snapshot();const temp=document.createElement('canvas');temp.width=temp.height=512;const t=temp.getContext('2d');t.drawImage(im,0,0,512,512);const pixels=t.getImageData(0,0,512,512);for(let i=0;i<pixels.data.length;i+=4){const a=(pixels.data[i]+pixels.data[i+1]+pixels.data[i+2])/3*pixels.data[i+3]/255>=128?255:0;pixels.data[i]=pixels.data[i+1]=pixels.data[i+2]=255;pixels.data[i+3]=a}pctx.putImageData(pixels,0,0);resetResult();renderMask()}
async function loadDemo(){if(busy)return;const reference=$('backbone').value==='reference';const response=await fetch('/api/demo'+(reference?'?reference=1':''));const data=await response.json();if(!response.ok)throw new Error(data.error);const nextImage=await imageFrom(data.image);references=(data.references||[]).map((data,index)=>({name:'Sample reference '+(index+1),data}));renderReferences();original=nextImage;$('framing').value='crop';frame();applyMask(await imageFrom(data.mask));undo=[];$('sourceName').textContent='Synthetic occlusion sample';notice(reference?'Sample loaded with four matching reference photos. Click Reconstruct face.':'Sample loaded with the complete damage mask. Click Reconstruct face, then inspect the full restored image.');controls()}
function point(event){const r=overlay.getBoundingClientRect();return {x:Math.max(0,Math.min(512,(event.clientX-r.left)/r.width*512)),y:Math.max(0,Math.min(512,(event.clientY-r.top)/r.height*512))}}
function stroke(a,b){pctx.globalCompositeOperation=tool==='erase'?'destination-out':'source-over';pctx.strokeStyle='#fff';pctx.fillStyle='#fff';pctx.lineCap=pctx.lineJoin='round';pctx.lineWidth=Number($('brush').value);pctx.beginPath();pctx.moveTo(a.x,a.y);pctx.lineTo(b.x,b.y);pctx.stroke();pctx.beginPath();pctx.arc(b.x,b.y,pctx.lineWidth/2,0,Math.PI*2);pctx.fill();pctx.globalCompositeOperation='source-over';renderMask()}
overlay.addEventListener('pointerdown',e=>{if(!loaded||busy)return;e.preventDefault();overlay.focus();overlay.setPointerCapture(e.pointerId);snapshot();resetResult();drawing=true;last=point(e);stroke(last,last)});overlay.addEventListener('pointermove',e=>{if(!drawing)return;const next=point(e);stroke(last,next);last=next});for(const type of ['pointerup','pointercancel','lostpointercapture'])overlay.addEventListener(type,()=>{drawing=false;last=null});
$('paint').onclick=()=>{tool='paint';$('paint').setAttribute('aria-pressed','true');$('erase').setAttribute('aria-pressed','false')};$('erase').onclick=()=>{tool='erase';$('paint').setAttribute('aria-pressed','false');$('erase').setAttribute('aria-pressed','true')};$('undo').onclick=()=>{if(undo.length&&!busy){pctx.putImageData(undo.pop(),0,0);resetResult();renderMask()}};$('clear').onclick=()=>{if(busy)return;snapshot();pctx.clearRect(0,0,512,512);resetResult();renderMask()};overlay.onkeydown=e=>{if((e.ctrlKey||e.metaKey)&&e.key==='z'){e.preventDefault();$('undo').click()}};$('brush').oninput=()=>$('brushValue').textContent=$('brush').value+' px';$('showMask').onchange=renderMask;$('framing').onchange=()=>{frame();notice('Framing updated. Paint a new mask for this frame.')};
$('imageFile').onchange=async e=>{try{if(e.target.files[0])await loadImage(e.target.files[0])}catch(error){notice(error.message,true)}finally{e.target.value=''}};$('maskFile').onchange=async e=>{try{if(!loaded)throw new Error('Upload a face before its mask.');const file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024)throw new Error('Use a mask smaller than 10 MB.');const url=URL.createObjectURL(file);try{applyMask(await imageFrom(url));notice('Mask loaded and fitted to the displayed square frame.')}finally{URL.revokeObjectURL(url)}}catch(error){notice(error.message,true)}finally{e.target.value=''}};
const drop=$('dropzone');drop.addEventListener('dragover',e=>{e.preventDefault();if(!busy)drop.classList.add('dragging')});drop.addEventListener('dragleave',()=>drop.classList.remove('dragging'));drop.addEventListener('drop',async e=>{e.preventDefault();drop.classList.remove('dragging');try{if(e.dataTransfer.files[0])await loadImage(e.dataTransfer.files[0])}catch(error){notice(error.message,true)}});$('sample').onclick=()=>loadDemo().catch(e=>notice(e.message,true));
$('mode').onchange=()=>{$('modeHint').textContent={expand:'Covers missed edges, but may also replace nearby valid pixels.',painted:'Replaces only the pixels inside your mask.',learned:'A research control. It can miss damage or replace valid pixels; it is not a verified quality upgrade.'}[$('mode').value]};
function exportMask(){const c=document.createElement('canvas');c.width=c.height=512;const t=c.getContext('2d');t.fillStyle='black';t.fillRect(0,0,512,512);t.drawImage(paintCanvas,0,0);return c.toDataURL('image/png')}
function compare(){$('inputTag').hidden=Number($('compare').value)===100;$('comparisonLine').hidden=[0,100].includes(Number($('compare').value));$('afterImage').style.clipPath=`inset(0 ${100-Number($('compare').value)}% 0 0)`;$('comparisonLine').style.left=$('compare').value+'%'}$('compare').oninput=compare;
async function reconstruct(){if(busy)throw new Error('A run is already in progress.');if(!loaded||!maskPresent())throw new Error('Paint or upload a mask first.');if($('backbone').value==='reference'&&references.length<3)throw new Error('Add three or four reference photos first.');busy=true;currentJob=null;lastError=null;resetResult();controls();$('working').hidden=false;$('workingText').textContent='Preparing your image…';notice('Processing locally. The first run includes model loading.');try{const sessionResponse=await fetch('/api/session');if(!sessionResponse.ok)throw new Error('The local server is unavailable.');token=(await sessionResponse.json()).token;const response=await fetch('/api/inpaint',{method:'POST',headers:{'Content-Type':'application/json','X-Local-Token':token},body:JSON.stringify({image:source.toDataURL('image/png'),mask:exportMask(),backbone:$('backbone').value,mode:$('mode').value,blend:$('blend').checked?'poisson':'hard',detail:$('detail').value,references:references.map(r=>r.data)})});const job=await response.json();if(!response.ok)throw new Error(job.error||'Could not start the run.');currentJob={id:job.id,status:'running'};let result;for(;;){await new Promise(resolve=>setTimeout(resolve,750));const check=await fetch('/api/jobs/'+job.id);result=await check.json();if(!check.ok)throw new Error(result.error);currentJob=result;$('workingText').textContent=result.message;if(result.status==='error')throw new Error(result.message);if(result.status==='complete')break}await Promise.all([imageFrom(result.result),imageFrom(result.input)]);$('beforeImage').src=result.input;$('afterImage').src=result.result;$('comparison').hidden=false;$('emptyResult').hidden=true;$('compare').disabled=false;$('compare').value='100';compare();for(const [id,url] of [['download',result.result],['downloadMask',result.mask]]){$(id).href=url;$(id).classList.remove('disabled');$(id).setAttribute('aria-disabled','false')}$('resultBadge').textContent=`${result.resolution||256} × ${result.resolution||256} · PNG`;notice(`Restoration ready. Reconstruction took ${result.seconds.toFixed(2)} seconds after loading. Drag the comparison slider to inspect the result.`);return {id:job.id,status:'complete',result:result.result}}catch(error){lastError=error.message;notice(error.message,true);throw error}finally{busy=false;$('working').hidden=true;controls()}}
$('run').onclick=()=>reconstruct().catch(e=>notice(e.message,true));
async function initialize(){try{const response=await fetch('/api/session');const session=await response.json();if(!response.ok)throw new Error('The local server is unavailable.');token=session.token;await loadDemo()}catch(e){notice(e.message,true)}if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});for(const spec of [{name:'get_inpainting_state',title:'Read inpainting workspace',description:'Read whether an image and mask are ready and which local model is selected.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({imageLoaded:loaded,maskPresent:maskPresent(),busy,referenceCount:references.length,backbone:$('backbone').value,mode:$('mode').value,edgeBlending:$('blend').checked,detail:$('detail').value,job:currentJob,error:lastError})},{name:'run_local_inpainting',title:'Reconstruct the current face',description:'Start GPU reconstruction of the current image and mask. Returns immediately; read get_inpainting_state for progress and the completed result.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(input&&Object.keys(input).length)throw new Error('This tool accepts no parameters.');if(busy)throw new Error('A run is already in progress.');if(!loaded||!maskPresent())throw new Error('Paint or upload a mask first.');if($('backbone').value==='reference'&&references.length<3)throw new Error('Add three or four reference photos first.');reconstruct().catch(()=>{});return {status:'started'}}}]){try{await document.modelContext.registerTool(spec,{signal:lifecycle.signal})}catch(error){console.warn('Optional WebMCP registration unavailable',error)}}}}

function renderReferences(){
  $('referenceList').replaceChildren();
  references.forEach((reference,index)=>{const item=document.createElement('div');item.className='reference-item';const image=document.createElement('img');image.src=reference.data;image.alt=`Reference photo ${index+1}`;const remove=document.createElement('button');remove.type='button';remove.textContent='×';remove.setAttribute('aria-label',`Remove reference ${index+1}`);remove.onclick=()=>{if(busy)return;references.splice(index,1);renderReferences()};item.append(image,remove);$('referenceList').append(item)});
  $('referenceCount').textContent=`${references.length} of 4 photos added`;controls();
}
$('backbone').onchange=()=>{const reference=$('backbone').value==='reference';$('referencePanel').hidden=!reference;$('outputNote').textContent=reference?'Output: 512 × 512 PNG · slower first run':'Output: 256 × 256 PNG';$('mode').querySelector('[value=learned]').disabled=reference;if(reference&&$('mode').value==='learned'){$('mode').value='expand';$('mode').dispatchEvent(new Event('change'))}controls()};
$('referenceFiles').onchange=async event=>{try{if(busy)return;const files=[...event.target.files];if(references.length+files.length>4)throw new Error('Use up to four reference photos. Remove one before adding another.');const added=[];for(const file of files){if(file.size>20*1024*1024)throw new Error('Each reference photo must be smaller than 20 MB.');const url=URL.createObjectURL(file);try{const image=await imageFrom(url),canvas=document.createElement('canvas'),scale=Math.min(1,512/Math.max(image.naturalWidth,image.naturalHeight));canvas.width=Math.round(image.naturalWidth*scale);canvas.height=Math.round(image.naturalHeight*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);added.push({name:file.name,data:canvas.toDataURL('image/png')})}finally{URL.revokeObjectURL(url)}}references.push(...added);renderReferences();notice('Reference photos added. Mark the damaged input area, then reconstruct.')}catch(error){notice(error.message,true)}finally{event.target.value=''}};
initialize();

